import { test } from 'node:test';
import assert from 'node:assert/strict';
import { ordemMicroMacro } from './solution.mjs';

test('registra a ordem completa: inicio, microtarefa, macrotarefa, fim', async () => {
  assert.deepEqual(await ordemMicroMacro(5), ['inicio', 'microtarefa', 'macrotarefa', 'fim']);
});

test('a ordem é a mesma com outro valor de ms', async () => {
  assert.deepEqual(await ordemMicroMacro(9), ['inicio', 'microtarefa', 'macrotarefa', 'fim']);
});

test('rejeita quando ms não é maior que zero', async () => {
  await assert.rejects(() => ordemMicroMacro(0), /maior que zero/);
});

solutionCode:
export async function ordemMicroMacro(ms) {
  if (typeof ms !== 'number' || ms < 1) {
    throw new Error('ms deve ser um número maior que zero');
  }
  const ordem = [];
  ordem.push('inicio'); // 1. parte síncrona da função

  // macrotarefa: entra na fila de timers e só dispara no próximo turno
  setTimeout(() => ordem.push('macrotarefa'), ms);

  // a continuação do await vira uma MICROtarefa: roda ainda neste turno,
  // ANTES de qualquer macrotarefa — mesmo tendo sido agendada depois
  await Promise.resolve();
  ordem.push('microtarefa'); // 2. antes da macrotarefa

  // agora sim espera a fase de timers disparar
  await new Promise((resolve) => setTimeout(resolve, ms));
  ordem.push('fim'); // 3. por último

  return ordem;
}
